      guided: [
        { id: 'g1', kind: 'num', q: 'Angular magnification of a magnifier with f = 5.0 cm (relaxed eye)?', answer: 5, unit: '×', calc: 'P.magnifierAngular(0.05)', hints: ['M = 25 cm/f.'], solution: 'M = 25/5.0 = 5.0×.' },
        { id: 'g2', kind: 'num', q: 'Magnitude of the magnification of a telescope with f_o = 90 cm and f_e = 2.5 cm?', answer: 36, unit: '×', calc: '90 / 2.5', hints: ['|M| = f_o/f_e.'], solution: '90/2.5 = 36×.' },
      ],
      practice: [
        { id: 'p1', kind: 'num', q: 'A nearsighted person has a far point of 2.0 m. Power of the corrective lens (worn close to the eye)?', answer: -0.5, unit: 'D', calc: 'P.lensPower(-2.0)', solution: 'f = −2.0 m → P = −0.50 D (diverging).' },
        { id: 'p2', kind: 'num', q: 'A farsighted person’s near point is 75 cm. What lens power lets them read at 25 cm?', answer: 2.67, unit: 'D', calc: '1 / 0.25 - 1 / 0.75', solution: 'Object at 0.25 m, virtual image at −0.75 m: P = 1/0.25 − 1/0.75 = 4.00 − 1.33 = +2.67 D.' },
        { id: 'p3', kind: 'num', q: 'A microscope has f_o = 0.40 cm, f_e = 2.5 cm, and tube length 16 cm. Magnitude of its magnification?', answer: 400, unit: '×', calc: '(16 / 0.40) * (25 / 2.5)', solution: '(16/0.40)(25/2.5) = 40 × 10 = 400×.' },
        { id: 'p4', kind: 'mc', q: 'The main reason large astronomical telescopes have huge objectives is to…', choices: ['increase magnification', 'gather more light and resolve finer detail', 'shorten the tube', 'remove color'], correct: 1, solution: 'Light-gathering area ∝ D², and resolution improves with D (Section 14.8).' },
        { id: 'p5', kind: 'mc', q: 'The human eye focuses on objects at different distances by…', choices: ['moving the lens forward and back', 'changing the shape of the lens', 'changing the pupil size only', 'moving the retina'], correct: 1, solution: 'Accommodation: ciliary muscles reshape the lens. Cameras move the lens instead.' },
      ],
